frappe.ui.form.on("Purchase Invoice", {
    before_submit: (frm) => {
        const codes = [...new Set((frm.doc.items || []).map((r) => r.item_code).filter(Boolean))];
        if (!codes.length) return;
        return new Promise((resolve, reject) => {
            frappe.call({
                method: "frappe.client.get_list",
                args: { doctype: "Item", filters: [["name", "in", codes]],
                    fields: ["name", "item_name"], limit_page_length: 0 },
            }).then((r) => {
                const bad = (r.message || []).filter((i) => (i.item_name || "").toUpperCase().startsWith("NEW_"));
                if (bad.length) {
                    const rows = bad.map((i) =>
                        `<li><a href="/app/item/${encodeURIComponent(i.name)}" target="_blank">${frappe.utils.escape_html(i.item_name)}</a> (${frappe.utils.escape_html(i.name)})</li>`).join("");
                    frappe.msgprint({
                        title: __("Cannot submit — new items need master data"),
                        indicator: "red",
                        message: __("These items still have temporary NEW_ names. Fix the item master data (name, units of measure) before submitting:") + `<ul>${rows}</ul>`,
                    });
                    reject();
                } else {
                    resolve();
                }
            });
        });
    },
});
